<?php
namespace AsdeBalears\AreaPrivada\Idiomas;

defined( 'ABSPATH' ) || exit;

/**
 * Textos que el plugin guarda o define en castellano como datos (semillas, plantillas, biblioteca de recetas,
 * nombres de roles, descripciones de permisos…) y que se traducen al mostrarlos: la búsqueda por el texto en castellano
 * devuelve la traducción de WordPress (doc 62). Los originales de la traducción están en inglés, con llamadas __()
 * literales para que translate.wordpress.org los recoja. Lo que no está aquí (un texto escrito por una persona) se
 * muestra tal cual.
 *
 * Generado desde traducciones/es-en.json; para añadir un texto, añádelo aquí con su original en inglés.
 */
final class Guardados {

	/** @var array<string, string> */
	private static array $mapa = array();

	private static string $idioma = '';

	/** Traducción de un texto guardado en castellano (o el propio texto si no es uno de los conocidos). */
	public static function t( string $es ): string {
		$idioma = determine_locale();
		if ( self::$idioma !== $idioma ) {
			self::$mapa   = self::mapa();
			self::$idioma = $idioma;
		}
		return self::$mapa[ $es ] ?? $es;
	}

	/** Se olvida lo calculado (pruebas y cambios de idioma en una misma petición). */
	public static function olvidar(): void {
		self::$mapa   = array();
		self::$idioma = '';
	}

